   758|export async function getIVXOwnerVariableRuntimeValue(
   759|  name: OwnerVariableName,
   760|  options: { preferStored?: boolean } = {},
   761|): Promise<string> {
   762|  const envValue = readEnv(name);
   763|  if (envValue && !options.preferStored) return envValue;
   764|  try {
   765|    const row = await getStoredRow(name);
   766|    if (!row) return envValue;
   767|    const decrypted = tryDecryptRowValue(row);
   768|    if (!decrypted) {
   769|      console.log('[IVXOwnerVariables] Runtime value bridge: decryption failed for all key candidates', {
   770|        name,
   771|        maskedPreview: row.masked_preview,
   772|      });
   773|      return '';
   774|    }
   775|    // Auto-reencrypt with the primary key if a fallback key was used (key rotation)
   776|    if (decrypted.keyIndex > 0) {
   777|      const plaintext = decrypted.plaintext.trim();
   778|      try {
   779|        await reencryptStoredRow(name, plaintext);
   780|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encrypted stale-key row with primary key', {
   781|          name,
   782|          keyIndex: decrypted.keyIndex,
   783|        });
   784|      } catch (reencryptError) {
   785|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encryption failed (returning decrypted value anyway)', {
   786|          name,
   787|          message: reencryptError instanceof Error ? sanitizeExternalErrorDetail(reencryptError.message) : 'unknown',
   788|        });
   789|      }
   790|      return plaintext;
   791|    }
   792|    return decrypted.plaintext.trim();
   793|  } catch (error) {
   794|    console.log('[IVXOwnerVariables] Runtime REST value bridge unavailable; trying direct Postgres fallback:', {
   795|      name,
   796|      message: error instanceof Error ? sanitizeExternalErrorDetail(error.message) : 'unknown',
   797|    });
   798|    if (getDatabaseUrl()) {
   799|      try {
   800|        const row = await withClient(async (client) => {
   801|          const result = await client.query<OwnerVariableRow>(
   802|            'select * from public.ivx_owner_variables where name = $1 limit 1',
   803|            [name],
   804|          );
   805|          return result.rows[0] ?? null;
   806|        });
   807|        if (row) {
   808|          const decrypted = tryDecryptRowValue(row);
   809|          if (decrypted?.plaintext.trim()) {
   810|            return decrypted.plaintext.trim();
   811|          }
   812|        }
   813|      } catch (fallbackError) {
   814|        console.log('[IVXOwnerVariables] Direct Postgres runtime fallback unavailable:', {
   815|          name,
   816|          message: fallbackError instanceof Error ? sanitizeExternalErrorDetail(fallbackError.message) : 'unknown',
   817|        });
   818|      }
   819|    }
   820|    return envValue;
   821|  }
