   707|function buildProviderReadiness(rows: OwnerVariableRow[]): Record<OwnerVariableProvider, ProviderReadiness> {
   708|  const rowByName = new Map(rows.map((row) => [row.name, row]));
   709|  const providers = Array.from(new Set(OWNER_VARIABLES.map((item) => item.provider))) as OwnerVariableProvider[];
   710|  return Object.fromEntries(providers.map((provider) => {
   711|    const required = OWNER_VARIABLES.filter((item) => item.provider === provider && item.required).map((item) => item.name);
   712|    // A required variable is satisfied if it's in the encrypted store OR in the backend runtime env.
   713|    const saved = required.filter((name) => rowByName.has(name) || readEnv(name));
   714|    const missing = required.filter((name) => !rowByName.has(name) && !readEnv(name));
   715|    const providerRows = OWNER_VARIABLES.filter((item) => item.provider === provider).map((item) => rowByName.get(item.name)).filter((row): row is OwnerVariableRow => Boolean(row));
   716|    const hasInvalid = providerRows.some((row) => row.status === 'invalid');
   717|    const hasTested = required.length > 0 && required.every((name) => rowByName.get(name)?.status === 'tested');
   718|    const lastTestedAt = providerRows
   719|      .map((row) => row.last_tested_at)
   720|      .filter((value): value is string => Boolean(value))
   721|      .sort()
   722|      .at(-1) ?? null;
   723|    const status: ProviderReadiness['status'] = missing.length > 0 ? 'missing' : hasInvalid ? 'invalid' : hasTested ? 'tested' : 'saved';
   724|    return [provider, {
   725|      provider,
   726|      status,
   727|      requiredVariableNames: required,
   728|      savedVariableNames: saved,
   729|      missingVariableNames: missing,
   730|      lastTestedAt,
   731|      secretValuesReturned: false as const,
   732|    }];
   733|  })) as Record<OwnerVariableProvider, ProviderReadiness>;
