   757|/**
   758| * Reads one encrypted Owner Variable for backend runtime use without exposing it to API responses.
   759| */
   760|export async function getIVXOwnerVariableRuntimeValue(
   761|  name: OwnerVariableName,
   762|  options: { preferStored?: boolean } = {},
   763|): Promise<string> {
   764|  const envValue = readEnv(name);
   765|  if (envValue && !options.preferStored) return envValue;
   766|  try {
   767|    const row = await getStoredRow(name);
   768|    if (!row) return envValue;
