   770|    if (!decrypted) {
   771|      console.log('[IVXOwnerVariables] Runtime value bridge: decryption failed for all key candidates', {
   772|        name,
   773|        maskedPreview: row.masked_preview,
   774|      });
   775|      return '';
   776|    }
   777|    // Auto-reencrypt with the primary key if a fallback key was used (key rotation)
   778|    if (decrypted.keyIndex > 0) {
   779|      const plaintext = decrypted.plaintext.trim();
   780|      try {
   781|        await reencryptStoredRow(name, plaintext);
   782|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encrypted stale-key row with primary key', {
   783|          name,
   784|          keyIndex: decrypted.keyIndex,
   785|        });
   786|      } catch (reencryptError) {
   787|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encryption failed (returning decrypted value anyway)', {
   788|          name,
   789|          message: reencryptError instanceof Error ? sanitizeExternalErrorDetail(reencryptError.message) : 'unknown',
   790|        });
   791|      }
   792|      return plaintext;
   793|    }
   794|    return decrypted.plaintext.trim();
   795|  } catch (error) {
   796|    console.log('[IVXOwnerVariables] Runtime REST value bridge unavailable; trying direct Postgres fallback:', {
   797|      name,
   798|      message: error instanceof Error ? sanitizeExternalErrorDetail(error.message) : 'unknown',
   799|    });
   800|    if (getDatabaseUrl()) {
   801|      try {
   802|        const row = await withClient(async (client) => {
   803|          const result = await client.query<OwnerVariableRow>(
   804|            'select * from public.ivx_owner_variables where name = $1 limit 1',
   805|            [name],
   806|          );
   807|          return result.rows[0] ?? null;
   808|        });
   809|        if (row) {
   810|          const decrypted = tryDecryptRowValue(row);
   811|          if (decrypted?.plaintext.trim()) {
   812|            return decrypted.plaintext.trim();
   813|          }
   814|        }
   815|      } catch (fallbackError) {
   816|        console.log('[IVXOwnerVariables] Direct Postgres runtime fallback unavailable:', {
   817|          name,
   818|          message: fallbackError instanceof Error ? sanitizeExternalErrorDetail(fallbackError.message) : 'unknown',
   819|        });
   820|      }
   821|    }
   822|    return envValue;
   823|  }
