function getEncryptionKeyCandidates(): Buffer[] {
  const candidates: Buffer[] = [];
  const seen = new Set<string>();
  // Try explicit encryption key sources first, then the derived fallback.
  for (const source of [
    readEnv('IVX_OWNER_VARIABLES_ENCRYPTION_KEY'),
