    readEnv('JWT_SECRET'),
    deriveFallbackEncryptionKey(),
  ]) {
    if (!source || seen.has(source)) continue;
    seen.add(source);
    candidates.push(createHash('sha256').update(source, 'utf8').digest());
  }
  return candidates;
}

